        Apply(modelBuilder, "Tenants", "CK_Tenants_BaseCurrencyCanonical_C3", "[IsDeleted] = 1 OR (DATALENGTH([BaseCurrency]) = 6 AND [BaseCurrency] COLLATE Latin1_General_100_BIN2 LIKE N'[A-Z][A-Z][A-Z]')");
        Apply(modelBuilder, "Tenders", "CK_Tenders_BidValidityPeriodDays", "BidValidityPeriodDays IS NULL OR BidValidityPeriodDays > 0");
        Apply(modelBuilder, "VendorInvoice", "CK_VendorInvoice_AcceptedSupplyCoherent", "([AcceptedSupplyKind] IS NULL AND [AcceptedSupplySourceId] IS NULL AND [AcceptedSupplySourceReference] IS NULL AND [AcceptedSupplySnapshotHash] IS NULL AND [AcceptedSupplyValidatedAtUtc] IS NULL) OR ([AcceptedSupplyKind] BETWEEN 1 AND 3 AND [AcceptedSupplySourceId] IS NOT NULL AND LEN([AcceptedSupplySourceReference]) BETWEEN 1 AND 100 AND LEN([AcceptedSupplySnapshotHash]) = 64 AND [AcceptedSupplyValidatedAtUtc] IS NOT NULL)");
        Apply(modelBuilder, "VendorInvoice", "CK_VendorInvoice_AcceptedSupplyPurchaseOrder", "[AcceptedSupplyKind] IS NULL OR [AcceptedSupplyKind] = 3 OR [PurchaseOrderId] IS NOT NULL");
        Apply(modelBuilder, "VendorInvoice", "CK_VendorInvoice_TDC0504MatchingTolerances", "[MatchingPriceTolerancePercent] BETWEEN 0 AND 100 AND [MatchingQuantityTolerancePercent] BETWEEN 0 AND 100");
        Apply(modelBuilder, "VendorInvoice", "CK_VendorInvoice_TDC0504SnapshotHash", "[MatchingSnapshotHash] IS NULL OR LEN([MatchingSnapshotHash]) = 64");
        Apply(modelBuilder, "VendorPaymentAllocation", "CK_VendorPaymentAllocation_TDC0505Snapshot", "[PaymentReadinessSnapshotHash] IS NULL OR LEN([PaymentReadinessSnapshotHash]) = 64");
        Apply(modelBuilder, "WithholdingTaxCertificates", "CK_WithholdingTaxCertificates_Amounts", "[TaxableBase] >= 0 AND [WithholdingAmount] > 0 AND [NetPaidAmount] >= 0");
        Apply(modelBuilder, "WithholdingTaxCertificates", "CK_WithholdingTaxCertificates_Version", "[VersionNumber] >= 1");
        Apply(modelBuilder, "WithholdingTaxRemittanceLines", "CK_WithholdingTaxRemittanceLines_Amounts", "[TaxableBase] >= 0 AND [WithholdingAmount] > 0");
        Apply(modelBuilder, "WithholdingTaxRemittances", "CK_WithholdingTaxRemittances_Period", "[PeriodTo] >= [PeriodFrom] AND [DueDate] >= [PeriodTo]");
        Apply(modelBuilder, "WithholdingTaxRemittances", "CK_WithholdingTaxRemittances_Total", "[TotalWithholdingAmount] > 0");
    }

    private static void Apply(ModelBuilder modelBuilder, string table, string name, string sql)
    {
        var roots = modelBuilder.Model.GetEntityTypes()
            .Where(entity => entity.BaseType is null && entity.GetTableName() == table)
            .ToArray();
        if (roots.Length != 1)
            throw new InvalidOperationException($"Archived check-constraint table binding is not unique: {table}.");
        modelBuilder.Entity(roots[0].ClrType).ToTable(table, tableBuilder => tableBuilder.HasCheckConstraint(name, sql));
    }
}
